-- Seeded translations for published content

ON CONFLICT(trip_id, locale) DO UPDATE SET title=excluded.title, summary=excluded.summary, updated_at=datetime('now');

ON CONFLICT(item_id, locale) DO UPDATE SET place_name=excluded.place_name, notes=excluded.notes, how_i_got_there=excluded.how_i_got_there, country_name=excluded.country_name, updated_at=datetime('now');

ON CONFLICT(recommendation_id, locale) DO UPDATE SET title=excluded.title, summary=excluded.summary, commentary=excluded.commentary, updated_at=datetime('now');
