INSERT INTO trip_translations (trip_id, locale, title, summary, updated_at) VALUES
	('04d231fe-94f3-4299-a1d4-9572d3717397', 'it', 'Andalusia ed Estremadura: viaggio circolare da Madrid', 'In 4 giorni abbiamo visitato Toledo, Cáceres, Siviglia e Granada.', datetime('now')),
	('04d231fe-94f3-4299-a1d4-9572d3717397', 'es', 'Andalucía y Extremadura: viaje de ida y vuelta desde Madrid', 'En 4 días visitamos Toledo, Cáceres, Sevilla y Granada.', datetime('now')),
	('04d231fe-94f3-4299-a1d4-9572d3717397', 'de', 'Andalusien und Extremadura: Rundreise ab Madrid', 'In 4 Tagen besuchten wir Toledo, Cáceres, Sevilla und Granada.', datetime('now')),
	('04d231fe-94f3-4299-a1d4-9572d3717397', 'fr', 'Andalousie et Estrémadure : circuit au départ de Madrid', 'En 4 jours, nous avons visité Tolède, Cáceres, Séville et Grenade.', datetime('now')),
	('1af066dd-170a-4324-9b18-234b83add5c3', 'it', 'Bogotá', 'Ho passato tre giorni a Bogotá e l’ho trovata, come molte altre città sudamericane, molto diseguale. È stato piacevole passarci un paio di giorni: ci sono tante attrazioni storiche, bella architettura e una gastronomia fantastica.', datetime('now')),
	('1af066dd-170a-4324-9b18-234b83add5c3', 'es', 'Bogotá', 'Pasé tres días en Bogotá y la encontré, como muchas otras ciudades sudamericanas, muy desigual. Fue agradable pasar un par de días allí: hay muchas atracciones históricas, buena arquitectura y una gastronomía increíble.', datetime('now')),
	('1af066dd-170a-4324-9b18-234b83add5c3', 'de', 'Bogotá', 'Ich verbrachte drei Tage in Bogotá und fand die Stadt – wie viele andere südamerikanische Städte – sehr ungleich. Ein paar Tage dort zu verbringen war angenehm: es gibt viele historische Sehenswürdigkeiten, schöne Architektur und großartige Gastronomie.', datetime('now')),
	('1af066dd-170a-4324-9b18-234b83add5c3', 'fr', 'Bogota', 'J’ai passé trois jours à Bogota et l’ai trouvée, comme beaucoup d’autres villes sud-américaines, très inégalitaire. Y passer quelques jours était agréable : on y trouve de nombreuses attractions historiques, une belle architecture et une gastronomie formidable.', datetime('now')),
	('9faba48b-c14c-4b37-ba1c-92391f97e21b', 'it', 'Il Cairo', 'Siamo rimasti meravigliati dalla ricca storia della città, ma abbiamo anche trovato il centro piuttosto decadente — anche se accogliente con i turisti. La gente del posto ci ha trattati meravigliosamente.', datetime('now')),
	('9faba48b-c14c-4b37-ba1c-92391f97e21b', 'es', 'El Cairo', 'Nos maravilló la rica historia de la ciudad, pero también encontramos el centro bastante deteriorado — aunque amable con los turistas. La gente local nos trató de maravilla.', datetime('now')),
	('9faba48b-c14c-4b37-ba1c-92391f97e21b', 'de', 'Kairo', 'Wir waren von der reichen Geschichte der Stadt begeistert, fanden das Zentrum aber auch ziemlich heruntergekommen — wenngleich freundlich zu Touristen. Die Einheimischen haben uns wunderbar behandelt.', datetime('now')),
	('9faba48b-c14c-4b37-ba1c-92391f97e21b', 'fr', 'Le Caire', 'Nous avons été émerveillés par la riche histoire de la ville, mais avons aussi trouvé le centre assez délabré — bien qu’accueillant pour les touristes. Les habitants nous ont traités merveilleusement.', datetime('now')),
	('17945af5-11e5-4cec-b04d-c2cfe1043c87', 'it', 'Dubai', 'Un soggiorno all’InterContinental Dubai Marina — hotel meraviglioso, colazione fantastica e posizione molto comoda.', datetime('now')),
	('17945af5-11e5-4cec-b04d-c2cfe1043c87', 'es', 'Dubái', 'Una estancia en el InterContinental Dubai Marina — hotel maravilloso, desayuno increíble y una ubicación muy conveniente.', datetime('now')),
	('17945af5-11e5-4cec-b04d-c2cfe1043c87', 'de', 'Dubai', 'Ein Aufenthalt im InterContinental Dubai Marina — wunderbares Hotel, fantastisches Frühstück und sehr günstige Lage.', datetime('now')),
	('17945af5-11e5-4cec-b04d-c2cfe1043c87', 'fr', 'Dubaï', 'Un séjour à l’InterContinental Dubai Marina — hôtel merveilleux, petit-déjeuner formidable et emplacement très pratique.', datetime('now')),
	('363278e5-0e2a-4333-b4b8-86d0feb16661', 'it', 'Kenya', 'Da Nairobi a Mombasa con il treno SGR — un viaggio confortevole dopo una corsa ai posti, concluso con un arrivo notturno caotico.', datetime('now')),
	('363278e5-0e2a-4333-b4b8-86d0feb16661', 'es', 'Kenia', 'De Nairobi a Mombasa en el tren SGR — un viaje cómodo tras un ajetreo por los asientos, que terminó en una llegada nocturna caótica.', datetime('now')),
	('363278e5-0e2a-4333-b4b8-86d0feb16661', 'de', 'Kenia', 'Von Nairobi nach Mombasa mit dem SGR-Zug — eine komfortable Fahrt nach einem Gerangel um Sitzplätze, endend mit einer chaotischen nächtlichen Ankunft.', datetime('now')),
	('363278e5-0e2a-4333-b4b8-86d0feb16661', 'fr', 'Kenya', 'De Nairobi à Mombasa en train SGR — un trajet confortable après une ruée pour les places, se terminant par une arrivée nocturne chaotique.', datetime('now')),
	('9486d791-5a40-4160-996a-efb2d564717a', 'it', 'Lappeenranta', 'Bellissima in estate, con dintorni meravigliosi e tanti modi di stare a contatto con la natura. La città può sembrare vuota a chi arriva da latitudini più calde. La gente del posto è stata molto gentile, anche se la loro cultura dà priorità al rispetto totale dello spazio personale.', datetime('now')),
	('9486d791-5a40-4160-996a-efb2d564717a', 'es', 'Lappeenranta', 'Hermosa en verano, con un entorno increíble y muchas formas de pasar tiempo en la naturaleza. La ciudad puede sentirse vacía para quien viene de latitudes más cálidas. La gente local fue muy amable, aunque su cultura prioriza el respeto total al espacio individual.', datetime('now')),
	('9486d791-5a40-4160-996a-efb2d564717a', 'de', 'Lappeenranta', 'Im Sommer wunderschön, mit fantastischer Umgebung und vielen Möglichkeiten, Zeit in der Natur zu verbringen. Die Stadt kann sich für jemanden aus wärmeren Breiten leer anfühlen. Die Einheimischen waren sehr freundlich, auch wenn ihre Kultur den uneingeschränkten Respekt vor dem persönlichen Raum priorisiert.', datetime('now')),
	('9486d791-5a40-4160-996a-efb2d564717a', 'fr', 'Lappeenranta', 'Magnifique en été, avec des environs formidables et de nombreuses façons de passer du temps dans la nature. La ville peut sembler vide pour quelqu’un venant de latitudes plus chaudes. Les habitants étaient très gentils, même si leur culture privilégie le respect total de l’espace individuel.', datetime('now')),
	('791c5811-8889-43f8-9687-ec3f7d7dae2c', 'it', 'Lima', 'Tempo fantastico nella capitale. Ristoranti meravigliosi, vita notturna e sightseeing. Ho amato assolutamente la città, anche se ho trovato il centro un po’ decadente intorno alla piazza principale. Ho buoni amici in Perù ed è stato bello ritrovarsi.', datetime('now')),
	('791c5811-8889-43f8-9687-ec3f7d7dae2c', 'es', 'Lima', 'Una experiencia increíble en la capital. Restaurantes maravillosos, vida nocturna y turismo. Me encantó la ciudad, aunque encontré el centro algo deteriorado alrededor de la plaza central. Tengo buenos amigos en Perú y fue agradable reunirnos de nuevo.', datetime('now')),
	('791c5811-8889-43f8-9687-ec3f7d7dae2c', 'de', 'Lima', 'Fantastische Zeit in der Hauptstadt. Wunderbare Restaurants, Nachtleben und Sehenswürdigkeiten. Ich habe die Stadt absolut geliebt, auch wenn ich das Zentrum um den Hauptplatz herum heruntergekommen fand. Ich habe gute Freunde in Peru und es war schön, sich wiederzusehen.', datetime('now')),
	('791c5811-8889-43f8-9687-ec3f7d7dae2c', 'fr', 'Lima', 'Moment formidable dans la capitale. Merveilleux restaurants, vie nocturne et visites. J’ai absolument adoré la ville, même si j’ai trouvé le centre un peu délabré autour de la place centrale. J’ai de bons amis au Pérou et c’était agréable de se retrouver.', datetime('now')),
	('61cd2ffc-e518-4769-a166-f1b4b51b7cdd', 'it', 'Londra', 'Arrivo via Dover, poi in treno a Londra e fino al Generator Hostel.', datetime('now')),
	('61cd2ffc-e518-4769-a166-f1b4b51b7cdd', 'es', 'Londres', 'Llegué vía Dover, luego en tren a Londres y hasta el Generator Hostel.', datetime('now')),
	('61cd2ffc-e518-4769-a166-f1b4b51b7cdd', 'de', 'London', 'Ankunft über Dover, dann mit dem Zug nach London und weiter zum Generator Hostel.', datetime('now')),
	('61cd2ffc-e518-4769-a166-f1b4b51b7cdd', 'fr', 'Londres', 'Arrivée via Douvres, puis en train jusqu’à Londres et au Generator Hostel.', datetime('now')),
	('0a4b0fca-c733-4dde-ba74-00444521d756', 'it', 'Oslo', 'Un viaggio di lavoro di un giorno — solo fino all’aeroporto, che sembrava molto moderno.', datetime('now')),
	('0a4b0fca-c733-4dde-ba74-00444521d756', 'es', 'Oslo', 'Un viaje de trabajo de un día — solo hasta el aeropuerto, que se sentía muy moderno.', datetime('now')),
	('0a4b0fca-c733-4dde-ba74-00444521d756', 'de', 'Oslo', 'Eine eintägige Dienstreise — nur bis zum Flughafen, der sehr modern wirkte.', datetime('now')),
	('0a4b0fca-c733-4dde-ba74-00444521d756', 'fr', 'Oslo', 'Un voyage d’affaires d’une journée — seulement jusqu’à l’aéroport, qui paraissait très moderne.', datetime('now')),
	('635acca1-7b7c-4fbb-a9b6-fbf6dd271af0', 'it', 'Parigi', 'Un soggiorno nel maggio 2010 a pochi passi dal Centre Pompidou — semplice, confortevole e ben posizionato.', datetime('now')),
	('635acca1-7b7c-4fbb-a9b6-fbf6dd271af0', 'es', 'París', 'Una estancia en mayo de 2010 a poca distancia del Centre Pompidou — sencilla, cómoda y bien ubicada.', datetime('now')),
	('635acca1-7b7c-4fbb-a9b6-fbf6dd271af0', 'de', 'Paris', 'Ein Aufenthalt im Mai 2010 nur wenige Schritte vom Centre Pompidou — schlicht, komfortabel und gut gelegen.', datetime('now')),
	('635acca1-7b7c-4fbb-a9b6-fbf6dd271af0', 'fr', 'Paris', 'Un séjour en mai 2010 à deux pas du Centre Pompidou — simple, confortable et bien situé.', datetime('now')),
	('f4a6873f-7d27-4af3-a8d8-11a903e63f57', 'it', 'Salinas', 'Ero a Salinas per il matrimonio di un amico e mi sono fermato solo una notte.', datetime('now')),
	('f4a6873f-7d27-4af3-a8d8-11a903e63f57', 'es', 'Salinas', 'Estuve en Salinas para la boda de un amigo y me quedé solo una noche.', datetime('now')),
	('f4a6873f-7d27-4af3-a8d8-11a903e63f57', 'de', 'Salinas', 'Ich war in Salinas für die Hochzeit eines Freundes und blieb nur eine Nacht.', datetime('now')),
	('f4a6873f-7d27-4af3-a8d8-11a903e63f57', 'fr', 'Salinas', 'J’étais à Salinas pour le mariage d’un ami et je n’y suis resté qu’une nuit.', datetime('now')),
	('500b3575-25be-4c72-89d4-acd5df374f78', 'it', 'Salvador de Bahia', 'Carnevale a Salvador', datetime('now')),
	('500b3575-25be-4c72-89d4-acd5df374f78', 'es', 'Salvador de Bahía', 'Carnaval en Salvador', datetime('now')),
	('500b3575-25be-4c72-89d4-acd5df374f78', 'de', 'Salvador da Bahia', 'Karneval in Salvador', datetime('now')),
	('500b3575-25be-4c72-89d4-acd5df374f78', 'fr', 'Salvador de Bahia', 'Carnaval à Salvador', datetime('now')),
	('67dd7855-12ab-4fba-9749-beda27183255', 'it', 'Colonia del Sacramento', 'Colonia è piacevole per passarci una giornata. È una città tranquilla con un piccolo centro storico. I tramonti sul Río de la Plata sono bellissimi e a volte ci sono belle feste per tutta la famiglia, come murgas e carnevale. Ci sono stato diverse volte.', datetime('now')),
	('67dd7855-12ab-4fba-9749-beda27183255', 'es', 'Colonia del Sacramento', 'Colonia es agradable para pasar un día. Es un pueblo tranquilo con un pequeño casco antiguo. Las puestas de sol sobre el Río de la Plata son muy hermosas y a veces hay hermosas fiestas para toda la familia, como murgas y carnaval. He estado allí varias veces.', datetime('now')),
	('67dd7855-12ab-4fba-9749-beda27183255', 'de', 'Colonia del Sacramento', 'Colonia eignet sich gut für einen Tagesaufenthalt. Es ist eine ruhige Stadt mit einem kleinen Altstadtviertel. Die Sonnenuntergänge über dem Río de la Plata sind sehr schön, und gelegentlich gibt es schöne Feste für die ganze Familie, etwa Murgas und Karneval. Ich war schon mehrmals dort.', datetime('now')),
	('67dd7855-12ab-4fba-9749-beda27183255', 'fr', 'Colonia del Sacramento', 'Colonia est agréable pour y passer une journée. C’est une ville tranquille avec un petit quartier ancien. Les couchers de soleil sur le Río de la Plata sont très beaux, et il peut y avoir de belles fêtes pour toute la famille, comme les murgas et le carnaval. J’y suis allé plusieurs fois.', datetime('now')),
	('2bf93eff-81d8-41d2-8d94-5f02b9ff41a3', 'it', 'El Calafate', 'Visita di 4 giorni a El Calafate e El Chaltén', datetime('now')),
	('2bf93eff-81d8-41d2-8d94-5f02b9ff41a3', 'es', 'El Calafate', 'Visita de 4 días a El Calafate y El Chaltén', datetime('now')),
	('2bf93eff-81d8-41d2-8d94-5f02b9ff41a3', 'de', 'El Calafate', '4-tägiger Besuch in El Calafate und El Chaltén', datetime('now')),
	('2bf93eff-81d8-41d2-8d94-5f02b9ff41a3', 'fr', 'El Calafate', 'Visite de 4 jours à El Calafate et El Chaltén', datetime('now')),
	('8ab240c0-d12a-4ebb-b389-af971e7c03f8', 'it', 'Kilimanjaro', 'Percorso Machame (whiskey) di 5 giorni', datetime('now')),
	('8ab240c0-d12a-4ebb-b389-af971e7c03f8', 'es', 'Kilimanjaro', 'Ruta Machame (whiskey) de 5 días', datetime('now')),
	('8ab240c0-d12a-4ebb-b389-af971e7c03f8', 'de', 'Kilimandscharo', '5-tägige Machame-(Whiskey-)Route', datetime('now')),
	('8ab240c0-d12a-4ebb-b389-af971e7c03f8', 'fr', 'Kilimandjaro', 'Route Machame (whiskey) en 5 jours', datetime('now')),
	('ac217a2b-779a-42c8-a46b-189691637d52', 'it', 'Miami', 'Miami è stata fantastica!', datetime('now')),
	('ac217a2b-779a-42c8-a46b-189691637d52', 'es', 'Miami', '¡Miami estuvo increíble!', datetime('now')),
	('ac217a2b-779a-42c8-a46b-189691637d52', 'de', 'Miami', 'Miami war fantastisch!', datetime('now')),
	('ac217a2b-779a-42c8-a46b-189691637d52', 'fr', 'Miami', 'Miami était formidable !', datetime('now')),
	('seed-trip-1', 'it', 'Lisbona a fine primavera', 'Tram, miradouros all’ora dorata e l’odore dei pastéis dopo una salita ripida.', datetime('now')),
	('seed-trip-1', 'es', 'Lisboa a finales de primavera', 'Tranvías, miradouros a la hora dorada y el olor de pastéis tras una subida empinada.', datetime('now')),
	('seed-trip-1', 'de', 'Lissabon im späten Frühling', 'Straßenbahnen, Miradouros zur goldenen Stunde und der Duft von Pastéis nach einem steilen Aufstieg.', datetime('now')),
	('seed-trip-1', 'fr', 'Lisbonne à la fin du printemps', 'Tramways, miradouros à l’heure dorée, et l’odeur des pastéis après une montée raide.', datetime('now'))
INSERT INTO itinerary_item_translations (item_id, locale, place_name, notes, how_i_got_there, country_name, updated_at) VALUES
	('d98322da-e7f2-4bb6-aeb5-2fa399312389', 'it', 'Madrid Puerta de Atocha - Almudena Grandes', 'Non ricordo il posto in cui alloggiavo', 'Alloggiavo in un Airbnb qui vicino e sono venuto a piedi.', 'Spagna', datetime('now')),
	('d98322da-e7f2-4bb6-aeb5-2fa399312389', 'es', 'Madrid Puerta de Atocha - Almudena Grandes', 'No recuerdo el lugar donde me alojaba', 'Me alojaba en un Airbnb cerca y simplemente fui caminando.', 'España', datetime('now')),
	('d98322da-e7f2-4bb6-aeb5-2fa399312389', 'de', 'Madrid Puerta de Atocha - Almudena Grandes', 'Ich erinnere mich nicht mehr an die Unterkunft', 'Ich wohnte in einem Airbnb in der Nähe und bin einfach hinübergelaufen.', 'Spanien', datetime('now')),
	('d98322da-e7f2-4bb6-aeb5-2fa399312389', 'fr', 'Madrid Puerta de Atocha - Almudena Grandes', 'Je ne me souviens plus de l’endroit où je logeais', 'Je logeais dans un Airbnb tout près et j’y suis allé à pied.', 'Espagne', datetime('now')),
	('6c1fe1eb-3634-4a83-ad29-487ad5b99d19', 'it', 'Hilton Bogotá', 'Bellissimo hotel, in una posizione meravigliosa, e con una colazione fantastica.', 'Transfer privato dall’aeroporto', 'Colombia', datetime('now')),
	('6c1fe1eb-3634-4a83-ad29-487ad5b99d19', 'es', 'Hilton Bogotá', 'Hotel hermoso, con una ubicación maravillosa y un desayuno increíble.', 'Traslado privado desde el aeropuerto', 'Colombia', datetime('now')),
	('6c1fe1eb-3634-4a83-ad29-487ad5b99d19', 'de', 'Hilton Bogotá', 'Wunderschönes Hotel, hervorragend gelegen, mit einem fantastischen Frühstück.', 'Privater Transfer vom Flughafen', 'Kolumbien', datetime('now')),
	('6c1fe1eb-3634-4a83-ad29-487ad5b99d19', 'fr', 'Hilton Bogota', 'Bel hôtel, superbement situé, avec un petit-déjeuner formidable.', 'Transfert privé depuis l’aéroport', 'Colombie', datetime('now')),
	('c4d7bd0c-4964-4ba1-951f-2e212e358356', 'it', 'Pyramisa Hotel', 'Soggiorno dal 15 al 20 aprile 2022 (circa quattro giorni). L’hotel sembrava piuttosto decadente; non ci è piaciuta la colazione.', 'Bus dall’aeroporto; taxi di ritorno all’aeroporto in partenza', 'Egitto', datetime('now')),
	('c4d7bd0c-4964-4ba1-951f-2e212e358356', 'es', 'Pyramisa Hotel', 'Estancia del 15 al 20 de abril de 2022 (unos cuatro días). El hotel se sentía bastante deteriorado; no nos gustó el desayuno.', 'Autobús desde el aeropuerto; taxi de vuelta al aeropuerto a la salida', 'Egipto', datetime('now')),
	('c4d7bd0c-4964-4ba1-951f-2e212e358356', 'de', 'Pyramisa Hotel', 'Aufenthalt 15.–20. April 2022 (etwa vier Tage). Das Hotel wirkte ziemlich heruntergekommen; das Frühstück mochten wir nicht.', 'Bus vom Flughafen; Taxi zurück zum Flughafen bei der Abreise', 'Ägypten', datetime('now')),
	('c4d7bd0c-4964-4ba1-951f-2e212e358356', 'fr', 'Pyramisa Hotel', 'Séjour du 15 au 20 avril 2022 (environ quatre jours). L’hôtel paraissait assez délabré ; le petit-déjeuner ne nous a pas plu.', 'Bus depuis l’aéroport ; taxi retour à l’aéroport au départ', 'Égypte', datetime('now')),
	('8d6226f4-8cf0-4dc1-8fa0-e80b20ba19fd', 'it', 'InterContinental Dubai Marina', 'Soggiorno meraviglioso. Colazione fantastica e posizione molto comoda.', 'Taxi dall’aeroporto', 'Emirati Arabi Uniti', datetime('now')),
	('8d6226f4-8cf0-4dc1-8fa0-e80b20ba19fd', 'es', 'InterContinental Dubai Marina', 'Estancia maravillosa. Desayuno increíble y una ubicación muy conveniente.', 'Taxi desde el aeropuerto', 'Emiratos Árabes Unidos', datetime('now')),
	('8d6226f4-8cf0-4dc1-8fa0-e80b20ba19fd', 'de', 'InterContinental Dubai Marina', 'Wunderbarer Aufenthalt. Fantastisches Frühstück und sehr günstige Lage.', 'Taxi vom Flughafen', 'Vereinigte Arabische Emirate', datetime('now')),
	('8d6226f4-8cf0-4dc1-8fa0-e80b20ba19fd', 'fr', 'InterContinental Dubai Marina', 'Séjour merveilleux. Petit-déjeuner formidable et emplacement très pratique.', 'Taxi depuis l’aéroport', 'Émirats arabes unis', datetime('now')),
	('e9d02b84-de8f-42b4-9bda-2fecf0c41f5c', 'it', 'Nairobi Terminus', 'Impossibile prenotare un posto in anticipo; all’arrivo dicevano che non ne restavano. Dopo una lunga discussione mi hanno dato due posti diversi che avrei dovuto cambiare a metà viaggio — non l’ho fatto. Stazione e treno erano confortevoli.', 'Uber dall’aeroporto al mattino presto', 'Kenya', datetime('now')),
	('e9d02b84-de8f-42b4-9bda-2fecf0c41f5c', 'es', 'Nairobi Terminus', 'Imposible reservar un asiento con antelación; al llegar dijeron que no quedaban. Tras una larga discusión me dieron dos asientos distintos que debía cambiar a mitad de camino — no lo hice. La estación y el tren eran cómodos.', 'Uber desde el aeropuerto temprano por la mañana', 'Kenia', datetime('now')),
	('e9d02b84-de8f-42b4-9bda-2fecf0c41f5c', 'de', 'Nairobi Terminus', 'Unmöglich, im Voraus einen Sitzplatz zu buchen; bei Ankunft hieß es, es seien keine mehr frei. Nach langer Diskussion gab man mir zwei verschiedene Plätze, die ich unterwegs hätte wechseln sollen — ich tat es nicht. Bahnhof und Zug waren komfortabel.', 'Uber vom Flughafen am frühen Morgen', 'Kenia', datetime('now')),
	('e9d02b84-de8f-42b4-9bda-2fecf0c41f5c', 'fr', 'Nairobi Terminus', 'Impossible de réserver une place à l’avance ; à l’arrivée, on m’a dit qu’il n’en restait plus. Après une longue discussion, on m’a donné deux places différentes que je devais changer en cours de route — je ne l’ai pas fait. La gare et le train étaient confortables.', 'Uber depuis l’aéroport tôt le matin', 'Kenya', datetime('now')),
	('c8190187-3130-4282-9443-95e64445a65c', 'it', 'Mombasa Terminus', 'Arrivo di notte. Trovare un taxi è sembrato piuttosto caotico.', 'Treno da Nairobi Terminus', 'Kenya', datetime('now')),
	('c8190187-3130-4282-9443-95e64445a65c', 'es', 'Mombasa Terminus', 'Llegué de noche. Encontrar un taxi se sintió bastante caótico.', 'Tren desde Nairobi Terminus', 'Kenia', datetime('now')),
	('c8190187-3130-4282-9443-95e64445a65c', 'de', 'Mombasa Terminus', 'Ankunft nachts. Ein Taxi zu finden wirkte ziemlich chaotisch.', 'Zug von Nairobi Terminus', 'Kenia', datetime('now')),
	('c8190187-3130-4282-9443-95e64445a65c', 'fr', 'Mombasa Terminus', 'Arrivée de nuit. Trouver un taxi a paru assez chaotique.', 'Train depuis Nairobi Terminus', 'Kenya', datetime('now')),
	('1040926f-bbca-46ba-aef3-34c24fc9b3a4', 'it', 'Casa di un amico a Pikisaari', 'Ospite di un amico a Pikisaari.', 'Treno da Helsinki a Lappeenranta; un amico mi ha preso alla stazione', 'Finlandia', datetime('now')),
	('1040926f-bbca-46ba-aef3-34c24fc9b3a4', 'es', 'Casa de un amigo en Pikisaari', 'Alojándome con un amigo en Pikisaari.', 'Tren de Helsinki a Lappeenranta; un amigo me recogió en la estación', 'Finlandia', datetime('now')),
	('1040926f-bbca-46ba-aef3-34c24fc9b3a4', 'de', 'Wohnung eines Freundes in Pikisaari', 'Bei einem Freund in Pikisaari untergebracht.', 'Zug von Helsinki nach Lappeenranta; ein Freund holte mich am Bahnhof ab', 'Finnland', datetime('now')),
	('1040926f-bbca-46ba-aef3-34c24fc9b3a4', 'fr', 'Chez un ami à Pikisaari', 'Hébergé chez un ami à Pikisaari.', 'Train d’Helsinki à Lappeenranta ; un ami m’a récupéré à la gare', 'Finlande', datetime('now')),
	('6a350520-2c9f-4c71-a203-f91fe094acda', 'it', 'Pariwana Hostel Lima', 'Era un ostello molto vivace, in una posizione meravigliosa nella zona più cosmopolita della città.', 'Taxi dall’aeroporto', 'Perù', datetime('now')),
	('6a350520-2c9f-4c71-a203-f91fe094acda', 'es', 'Pariwana Hostel Lima', 'Era un hostal muy animado, maravillosamente ubicado en la zona más cosmopolita de la ciudad.', 'Taxi desde el aeropuerto', 'Perú', datetime('now')),
	('6a350520-2c9f-4c71-a203-f91fe094acda', 'de', 'Pariwana Hostel Lima', 'Es war ein sehr lebendiges Hostel, wunderbar gelegen im kosmopolitischsten Viertel der Stadt.', 'Taxi vom Flughafen', 'Peru', datetime('now')),
	('6a350520-2c9f-4c71-a203-f91fe094acda', 'fr', 'Pariwana Hostel Lima', 'C’était une auberge très animée, superbement située dans le quartier le plus cosmopolite de la ville.', 'Taxi depuis l’aéroport', 'Pérou', datetime('now')),
	('5e97b84d-4f14-4c73-8101-15119cc3f74f', 'it', 'Porto di Dover', 'Prima tappa sulla strada verso l’Inghilterra.', NULL, 'Regno Unito', datetime('now')),
