	('seed-stop-2', 'es', 'Time Out Market', 'Aglomerado pero fácil para una primera cena.', 'Metro hasta Cais do Sodré', 'Portugal', datetime('now')),
	('seed-stop-2', 'de', 'Time Out Market', 'Voll, aber einfach für ein erstes Abendessen.', 'Metro nach Cais do Sodré', 'Portugal', datetime('now')),
	('seed-stop-2', 'fr', 'Time Out Market', 'Bondé mais pratique pour un premier dîner.', 'Métro jusqu’à Cais do Sodré', 'Portugal', datetime('now')),
