	('seed-stop-3', 'es', 'Monasterio de los Jerónimos', 'Id temprano, antes de que se formen las colas.', 'Tranvía 15 desde el centro', 'Portugal', datetime('now')),
	('seed-stop-3', 'de', 'Hieronymus-Kloster (Mosteiro dos Jerónimos)', 'Früh gehen, bevor sich Schlangen bilden.', 'Straßenbahn 15 vom Zentrum', 'Portugal', datetime('now')),
